import { AccountService } from '@app/services/account.service';
import { Router } from '@angular/router';
import { NgxSpinnerService } from 'ngx-spinner';
import { Component, OnInit, TemplateRef } from '@angular/core';
import { BsModalRef, BsModalService } from 'ngx-bootstrap/modal';
import { ToastrService } from 'ngx-toastr';
import { Evento } from '@app/models/Evento';
import { EventoService } from '@app/services/evento.service';
import { Pagination, PaginatedResult } from '@app/models/Pagination';
import { Subject } from 'rxjs';
import { debounceTime } from 'rxjs/operators';
import { environment } from '@environments/environment';

@Component({
  selector: 'app-evento-lista',
  templateUrl: './evento-lista.component.html',
  styleUrls: ['./evento-lista.component.scss'],
})
export class EventoListaComponent implements OnInit {
  modalRef!: BsModalRef;

  public eventos: Evento[] = [];
  public eventoId = 0;
  public numeroEvento = 0;
  public pagination = {} as Pagination;

  public larguraImagem = 150;
  public margemImagem = 2;
  public exibirImagem = true;

  termBuscaChanged: Subject<string> = new Subject<string>();

  public filtrarEventos(evt: any): void {
    const filtro = evt?.value ?? '';

    if (this.termBuscaChanged.observers.length === 0) {
      this.termBuscaChanged
        .pipe(debounceTime(1000))
        .subscribe((valor: string) => {
          this.eventoService
            .getEventos(
              this.pagination.currentPage,
              this.pagination.itemsPerPage,
              valor
            )
            .subscribe({
              next: (paginatedResult: PaginatedResult<Evento[]>) => {
                this.eventos = paginatedResult.result;
                this.pagination = paginatedResult.pagination;
              },
              error: () => {
                this.spinner.hide();
                this.toastr.error('Erro ao Carregar os Eventos', 'Erro!');
              },
            })
            .add(() => this.spinner.hide());
        });
    }

    this.termBuscaChanged.next(filtro);
  }

  constructor(
    private eventoService: EventoService,
    private modalService: BsModalService,
    private toastr: ToastrService,
    private spinner: NgxSpinnerService,
    private router: Router,
    public account: AccountService
  ) {}

  public ngOnInit(): void {
    this.account.getUser().subscribe({ error: () => {} });
    this.pagination = {
      currentPage: 1,
      itemsPerPage: 3,
      totalItems: 1,
    } as Pagination;
    this.carregarEventos();
  }

  public alterarImagem(): void {
    this.exibirImagem = !this.exibirImagem;
  }

  public carregarEventos(): void {
    this.eventoService
      .getEventos(this.pagination.currentPage, this.pagination.itemsPerPage)
      .subscribe(
        (paginatedResult: PaginatedResult<Evento[]>) => {
          this.eventos = paginatedResult.result;
          this.pagination = paginatedResult.pagination;
        },
        () => {
          this.spinner.hide();
          this.toastr.error('Erro ao Carregar os Eventos', 'Erro!');
        }
      )
      .add(() => this.spinner.hide());
  }

  public openModal(
    event: any,
    template: TemplateRef<any>,
    eventoId: number,
    numeroEvento: number
  ): void {
    event.stopPropagation();

    this.eventoId = eventoId;
    this.numeroEvento = numeroEvento;

    this.modalRef = this.modalService.show(template, { class: 'modal-sm' });
  }

  public pageChanged(event: any): void {
    this.pagination.currentPage = event.page;
    this.carregarEventos();
  }

  public confirm(): void {
    this.modalRef.hide();
    this.spinner.show();

    this.eventoService
      .deleteEvento(this.eventoId)
      .subscribe(
        (result: any) => {
          if (result.message === 'Deletado') {
            this.toastr.success('O Evento foi deletado com Sucesso.', 'Deletado!');
            this.carregarEventos();
          }
        },
        (error: any) => {
          console.error(error);
          this.toastr.error(`Erro ao tentar deletar o evento ${this.eventoId}`, 'Erro');
        }
      )
      .add(() => this.spinner.hide());
  }

  public decline(): void {
    this.modalRef.hide();
  }

  public detalheEvento(id: number): void {
    this.router.navigate([`eventos/detalhe/${id}`]);
  }

  public imagemEvento(nome: string): string {
    return nome ? environment.apiURL + 'resources/images/' + nome : 'assets/img/upload.png';
  }
}
