import { Component, OnInit, OnDestroy } from '@angular/core';
import { FormBuilder, FormGroup } from '@angular/forms';
import { PalestranteService } from '../../../services/palestrante.service';
import { ToastrService } from 'ngx-toastr';
import { NgxSpinnerService } from 'ngx-spinner';
import { map, debounceTime, finalize, takeUntil, timeout, tap } from 'rxjs/operators';
import { Subject } from 'rxjs';
import { Palestrante } from '@app/models/Palestrante';

@Component({
  selector: 'app-palestrante-detalhe',
  templateUrl: './palestrante-detalhe.component.html',
  styleUrls: ['./palestrante-detalhe.component.scss'],
})
export class PalestranteDetalheComponent implements OnInit, OnDestroy {
  private readonly destruir$ = new Subject<void>();
  public form!: FormGroup;
  public situacaoDoForm = '';
  public corDaDescricao = '';

  constructor(
    private fb: FormBuilder,
    public palestranteService: PalestranteService,
    private toastr: ToastrService,
    private spinner: NgxSpinnerService
  ) {}

  ngOnInit(): void {
    this.validation();
    this.verificaForm();
    this.carregarPalestrante();
  }

  ngOnDestroy(): void {
    this.destruir$.next();
    this.destruir$.complete();
    this.spinner.hide();
  }

  private validation(): void {
    this.form = this.fb.group({
      miniCurriculo: [''],
    });
  }

  private carregarPalestrante(): void {
    this.spinner.show();

    this.palestranteService
      .getPalestrante()
      .pipe(timeout(30000), takeUntil(this.destruir$), finalize(() => this.spinner.hide()))
      .subscribe(
        (palestrante: Palestrante) => {
          this.form.patchValue(palestrante, { emitEvent: false });
          this.situacaoDoForm = 'Minicurrículo foi carregado!';
          this.corDaDescricao = 'text-muted';
        },
        (error: any) => {
          this.toastr.error('Erro ao Carregar o Palestrante', 'Erro');
        }
      );
  }

  public get f(): any {
    return this.form.controls;
  }

  private verificaForm(): void {
    this.form.valueChanges
      .pipe(
        map(() => {
          this.situacaoDoForm = 'Minicurrículo está sendo Atualizado!';
          this.corDaDescricao = 'text-warning';
        }),
        debounceTime(1000),
        tap(() => this.spinner.show()),
        takeUntil(this.destruir$)
      )
      .subscribe(() => {
        this.palestranteService
          .put({...this.form.value })
          .pipe(timeout(30000), takeUntil(this.destruir$), finalize(() => this.spinner.hide()))
          .subscribe(
            () => {
              this.situacaoDoForm = 'Minicurrículo foi ataulizado!';
              this.corDaDescricao = 'text-success';

              setTimeout(() => {
                this.situacaoDoForm = 'Minicurrículo foi carregado!';
                this.corDaDescricao = 'text-muted';
              }, 2000);
            },
            () => {
              this.toastr.error('Erro ao tentar atualizar Palestrante', 'Erro');
            }
          );
      });
  }
}
